func (this *Bitbns) ParseTransactionStatusByType(status any, optionalArgs ...any) any {
	typeVar := GetArg(optionalArgs, 0, nil)
	_ = typeVar
	var statusesByType map[string]any = map[string]any{
		"deposit": map[string]any{
			"0": "pending",
			"1": "ok",
		},
		"withdrawal": map[string]any{
			"0": "pending",
			"1": "canceled",
			"2": "pending",
			"3": "failed",
			"4": "pending",
			"5": "failed",
			"6": "ok",
		},
	}
	var statuses any = this.SafeDict(statusesByType, typeVar, map[string]any{})
	return this.SafeString(statuses, status, status)
}
func (this *Bitbns) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDeposits
	//
	//     {
	//         "type":"USDT deposited",
	//         "typeI":1,
	//         "amount":100,
	//         "date":"2021-04-24T14:56:04.000Z",
	//         "unit":"USDT",
	//         "factor":100,
	//         "fee":0,
	//         "delh_btc":0,
	//         "delh_inr":0,
	//         "rate":0,
	//         "del_btc":10000,
	//         "del_inr":0
	//     }
	//
	// fetchWithdrawals
	//
	//     ...
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var currencyId any = this.SafeString(transaction, "unit")
	var code any = this.SafeCurrencyCode(currencyId, currency)
	var timestamp any = this.Parse8601(this.SafeString2(transaction, "date", "timestamp"))
	var typeVar any = this.SafeString(transaction, "type")
	var expTime any = this.SafeString(transaction, "expTime", "")
	var status any = nil
	if IsTrue(!IsEqual(typeVar, nil)) {
		if IsTrue(IsGreaterThanOrEqual(GetIndexOf(typeVar, "deposit"), 0)) {
			typeVar = "deposit"
			status = "ok"
		} else if IsTrue(IsTrue(IsGreaterThanOrEqual(GetIndexOf(typeVar, "withdraw"), 0)) || IsTrue(IsGreaterThanOrEqual(GetIndexOf(expTime, "withdraw"), 0))) {
			typeVar = "withdrawal"
		}
	}
	// const status = this.parseTransactionStatusByType (this.safeString (transaction, 'status'), type);
	var amount any = this.SafeNumber(transaction, "amount")
	var feeCost any = this.SafeNumber(transaction, "fee")
	var fee any = nil
	if IsTrue(!IsEqual(feeCost, nil)) {
		fee = map[string]any{
			"currency": code,
			"cost":     feeCost,
		}
	}
	return map[string]any{
		"info":        transaction,
		"id":          nil,
		"txid":        nil,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     nil,
		"address":     nil,
		"addressTo":   nil,
		"addressFrom": nil,
		"tag":         nil,
		"tagTo":       nil,
		"tagFrom":     nil,
		"type":        typeVar,
		"amount":      amount,
		"currency":    code,
		"status":      status,
		"updated":     nil,
		"comment":     nil,
		"internal":    nil,
		"fee":         fee,
	}
}

